// Raw discovery material. No novelty grades, scores, or sharpened verdicts.
// Each row expands to the complete candidate schema exported below.
const operator = (number, name) => (n, working_name, proposition, old_parents, level_of_analysis, timescale, variables, countervailing_intervention, why_not_old_paraphrase, track = 'A_SCIENTIFIC') => ({
  id: `D4:I${n}`, operator: { number, name }, working_name,
  proposition, old_parents, level_of_analysis,
  timescale, variables, countervailing_intervention, why_not_old_paraphrase, track,
  stage: 'RAW_UNSCORED', novelty_status: 'NOT_ASSESSED'
});

const authority = operator(8, 'authority without permission');
const authorityCandidates = [
  authority(106, 'Visitor history becomes evidence', 'If a household treats its robot log as the default account of disputed visits, then changing retention completeness can redistribute credibility between residents even when the robot has no permission to adjudicate disputes.', ['I024','I102'], 'household institution', 'months', ['log completeness','default evidentiary status','resident credibility'], 'Give residents an independent correction channel and compare credibility before and after contested logs are marked incomplete.', 'Adds institutional evidentiary adoption between sensing and household standing; the outcome is who is believed, not robot command scope.', 'B_EXPLANATORY'),
  authority(107, 'Tutor description becomes a role', 'If adults use a tutor profile to decide which responsibilities a child may attempt, then a correct but selectively sampled profile can restrict developmental opportunities without the tutor receiving disciplinary authority.', ['I028','I124','HS-C11'], 'child-family-school network', 'school years', ['sampled behavior','adult responsibility allocation','new task exposure'], 'Require periodic profile-free opportunities chosen by the child and an educator; compare later competence.', 'Connects descriptive labeling to allocation of developmental occasions by third parties; the profile can remain accurate and tutor permission fixed.'),
  authority(108, 'Care anticipation defines urgency', 'If caregivers schedule visits around an agent prediction of likely need, then unpredicted needs can become harder to establish as urgent because the schedule itself removes human witnesses.', ['HS-C29','I075'], 'care network', 'weeks to years', ['predicted need','visit allocation','witness availability','recognized urgency'], 'Reserve randomized human visits and allow recipient-defined urgency outside the forecast.', 'Adds a prediction-to-witness-to-urgency path rather than equating care task success with care quality.'),
  authority(109, 'Ritual logistics sets membership', 'If an agent arranges communal ritual participation by predicted reliability, then access to the acts through which membership is recognized can change without any grant of religious interpretive authority.', ['I037','I055','HS-C18'], 'religious community', 'ritual cycles', ['logistical eligibility','participation opportunity','recognized membership'], 'Let accountable local institutions allocate a protected share of participation outside predicted reliability.', 'Moves from nonfungible performance to the production of social standing through logistical eligibility.', 'B_EXPLANATORY'),
  authority(110, 'Common summary sets the question', 'If a council adopts one agent summary to define the alternatives for deliberation, then parties omitted from that summary must first contest the agenda before they can exercise equal voting rights.', ['I031','I149'], 'public institution', 'meetings to election cycles', ['agenda representation','admission cost','formal voting rights'], 'Permit a separately staffed agenda amendment period before any option ranking.', 'Separates equal decision rights from the cost of making a claim eligible for decision; the agent need not choose the outcome.', 'B_EXPLANATORY'),
  authority(111, 'Temporary routes become entitlements', 'If a building repeatedly accommodates robots through informal route concessions, then later occupants can inherit a practical expectation to yield even though no actor authorized a permanent right of way.', ['I030','I062','I133'], 'embodied shared space', 'months to building turnover', ['repeated yielding','route precedent','occupant turnover'], 'Time-limit route concessions and test accessibility when concessions expire.', 'Adds turnover and precedential expectations to individual navigation externalities.'),
  authority(112, 'Draft confidence allocates mentors', 'If supervisors route apparently difficult drafts to human mentors and easy drafts to agents, then an agent that makes uncertainty less visible can determine who receives expert attention without controlling personnel assignments.', ['I023','I065'], 'workplace training', 'training cohorts', ['visible uncertainty','mentor routing','subsequent independent competence'], 'Allocate some mentoring by novice learning needs rather than artifact polish.', 'Links uncertainty display to scarce mentoring allocation and future expertise, holding formal managerial rights fixed.'),
  authority(113, 'Interaction histories allocate forgiveness', 'If friends use an agent reconstruction of past exchanges to judge whether an apology is credible, then retrieval order can change willingness to repair a relationship without changing any stored fact.', ['HS-C12','I034','I073'], 'interpersonal relationship', 'conflicts across years', ['retrieval order','perceived recurrence','repair willingness'], 'Offer mutually chosen alternative history windows before adjudicating recurrence.', 'Makes temporally selected memory a determinant of forgiveness rather than prediction or data integrity.', 'B_EXPLANATORY'),
  authority(114, 'Continuing delegate occupies representation', 'If an organization continues accepting a deceased member agent as the most informed representative of that member interests, then living successors may bear proof burdens to exercise rights already transferred to them.', ['I026','HS-C38'], 'succession institution', 'months after death', ['informational advantage','recognized representative','successor proof burden'], 'Transfer recognized representation on the authority event while retaining the old agent only as a labeled evidence source.', 'Separates inherited informational expertise from inherited standing and tests burden on a new rights holder.'),
  authority(115, 'Safe motion teaches ownership', 'If children repeatedly see a robot retrieve contested objects without visible consultation, then they may learn an ownership norm from successful motion even where every retrieval was authorized only as a temporary exception.', ['I028','I024'], 'childhood embodied learning', 'months', ['exception frequency','visible consultation','ownership judgment transfer'], 'Display exception reasons and include contrasting cases with the same object and different rights holders.', 'Adds embodied observation of exceptions to the development of ownership concepts, not only compliance or persuasion.'),
  authority(116, 'Credential formatting sets expertise', 'If institutions accept agent-prepared demonstrations as evidence of practical expertise, then skill at fitting work to the demonstration format can acquire gatekeeping power over genuine but differently expressed competence.', ['I032','I063'], 'credential market', 'credential cycles', ['format fit','practical transfer','certification access'], 'Include unfamiliar-tool transfer and locally alternative demonstrations in assessment.', 'Couples agent-readable format conformity to certification rather than generic credential scarcity.'),
  authority(117, 'Recipient legibility outruns owner rights', 'If a care recipient can only make their needs legible through one agent translation while the device owner controls that translation, then the owner can shape institutional recognition of needs without changing the recipient legal rights.', ['I029','I044','HS-C21'], 'care institution', 'months', ['need translation','owner control','institutional recognition'], 'Allow recipient-controlled independent translation and compare recognition of identical reports.', 'Targets dependence on translation for standing rather than service exit or formal consent.'),
  authority(118, 'Public refusal becomes moral testimony', 'If bystanders interpret a robot refusal as evidence that a human request is improper, then refusal wording can impose reputational sanctions even when the robot has only a technical inability.', ['I004','I080'], 'public interaction', 'seconds to accumulated reputation', ['refusal explanation','audience inference','reputational sanction'], 'Require refusal messages to identify whether the cause is capability, policy, or disputed authority.', 'Adds third-party moral inference and sanction to refusal, without assuming actual moral jurisdiction.', 'B_EXPLANATORY'),
  authority(119, 'Welfare caution reallocates standing', 'If an institution treats an agent self-report as sufficient to pause human appeals pending welfare review, then procedural standing can shift before credible evidence of patienthood is established.', ['I143','HS-C40'], 'human-machine governance', 'review episodes', ['self-report threshold','appeal delay','independent evidence'], 'Use separately governed evidence thresholds and maintain a human appeal route during assessment.', 'Examines allocation of procedural delay under uncertainty, not a claim that self-report establishes welfare.'),
  authority(120, 'Convenient categories become reasons', 'If a public service repeatedly resolves cases using categories available in its agent interface, then claimants may have to redescribe their circumstances in those categories to receive a reasoned decision despite unchanged legal entitlements.', ['HS-C34','I120'], 'public administration', 'years', ['interface categories','claim redescription cost','reason recognition'], 'Permit uncategorized claims with independent interpretation and publish contested category cases.', 'Connects executable classification to the language of publicly acceptable reasons rather than merely accuracy or access.', 'B_EXPLANATORY')
];

const control = operator(9, 'permission without effective control');
const controlCandidates = [
  control(121, 'Household veto requires substitutes', 'If a resident may veto a care robot task only after arranging substitute labor, then formal veto availability can fall as other residents stop maintaining substitute routines.', ['I024','I072','I116'], 'household care', 'months', ['veto rule','substitute labor','routine maintenance'], 'Fund shared substitute arrangements before deployment and test veto exercise without emergency burden.', 'Makes other residents investment a mediator of veto feasibility; this differs from an individual off-switch or skill score.'),
  control(122, 'Child withdrawal leaves assessment traces', 'If a child may leave a tutor but schools retain its inferred difficulty labels, then service withdrawal does not restore the child opportunity to be assessed on new behavior.', ['I124','I153'], 'child-school network', 'school transitions', ['withdrawal','label persistence','new assessment opportunity'], 'Require fresh evidence after withdrawal and audit whether retired labels still route opportunities.', 'Separates termination from institutional supersession of interpretive evidence.'),
  control(123, 'Nonoverlapping validity defeats joint review', 'If each institution provides a sufficient local review period but its disclosed conditions expire asynchronously, then a shared action can lack any interval in which all conditions are simultaneously valid and reviewable; extending the final deadline alone will not restore effective joint review.', ['I054','I135','I151'], 'cross-institution workflow', 'versioned approval cycles', ['local review period','condition validity interval','joint overlap','final deadline'], 'Compare frozen joint-condition snapshots or coordinated validity intervals against final-deadline extension alone.', 'Adds intersection of institution-specific validity intervals and repeated reauthorization as the control obstacle; local comprehension time and total deadline can both be adequate.'),
  control(124, 'Appeal rights lose interpreters', 'If an institution preserves appeals but automates the junior work that trained appeal reviewers, then the rights can remain stable while their exercise becomes slower or more template-dependent.', ['I023','I120','I149'], 'public or professional institution', 'cohorts to a decade', ['appeal rights','reviewer pipeline','interpretive capacity'], 'Maintain supervised exception practice and measure appeal quality as well as throughput.', 'Couples a delayed labor reproduction state to effectiveness of an unchanged procedural right.'),
  control(125, 'Shared-space stop cannot undo adaptation', 'If residents can stop a robot deployment after buildings remove human-accessible routes, then stopping operation alone can leave non-users less mobile than before deployment.', ['I030','I062','I129'], 'building governance', 'construction to occupancy cycles', ['deployment veto','route removal','post-stop accessibility'], 'Require a funded restoration design before permanent route changes.', 'Outcome is infrastructure after successful veto, not whether the robot obeyed a stop command.'),
  control(126, 'Care data deletion removes contest evidence', 'If recipients can delete intimate care logs but those logs are the only evidence for contesting a harmful staffing decision, then privacy exercise and procedural redress can become mutually obstructive.', ['I017','I104','HS-C29'], 'care-data governance', 'dispute lifecycle', ['deletion rights','independent evidence','staffing appeal'], 'Maintain privacy-minimized independent dispute receipts that do not retain intimate content.', 'Adds an evidence-preservation conflict between two human rights rather than generic privacy versus model utility.', 'B_EXPLANATORY'),
  control(127, 'Exit carries unowned coordination work', 'If a companion user may exit immediately while their family calendars depend on the companion, then exit can require coordination work from people who never chose the service.', ['I018','I128','I137'], 'relationship network', 'weeks of transition', ['individual exit','shared commitments','third-party coordination'], 'Provide joint commitment transfer with limited affected-party access before termination.', 'Makes network commitments and non-user transition burden the outcome instead of incumbent switching loss.'),
  control(128, 'Independent practice loses legitimacy', 'If a worker may perform tasks unaided but quality rules require an agent trace, then unaided competence can remain technically possible while no longer counting as authorized evidence of good work.', ['I033','I063','I107'], 'work institution', 'months to accreditation cycles', ['unaided practice','trace requirement','recognized work quality'], 'Accept independently observed unaided cases as equivalent compliance evidence.', 'Separates ability to act from institutional acceptance of the resulting artifact; skill preservation alone cannot repair it.'),
  control(129, 'Community veto has no recognized speaker', 'If every affected household has a consultation right but the implementation recognizes only organizations as veto issuers, then a dispersed community can lack effective control despite unanimous private opposition.', ['I085','I129'], 'local plural authority', 'deployment disputes', ['consultation rights','issuer ontology','collective opposition'], 'Support locally chosen temporary representation and make contested standing visible.', 'Targets mismatch between procedural issuer types and collective agency, not merely absence of consultation.', 'B_EXPLANATORY'),
  control(130, 'Successor ownership cannot redirect promises', 'If a successor legally owns an inherited agent but counterparties rely on commitments made by its prior principal, then control of the software does not imply freedom to change its conduct without relational or contractual loss.', ['I026','I103','I128'], 'succession network', 'estate transition', ['software ownership','external commitments','redirection cost'], 'Inventory commitments separately from ownership and offer notice-bound release procedures.', 'Locates control constraints in third-party reliance after legal transfer, rather than in obsolete tokens.', 'B_EXPLANATORY'),
  control(131, 'Ritual exception changes the audience', 'If a person may decline agent participation in a ritual but the remaining community reorganizes around agent timing, then exercising the exception can remove access to the shared audience that gives the act meaning.', ['I037','I055','I040'], 'ritual community', 'annual or weekly cycles', ['individual exception','collective timing','shared audience'], 'Preserve community-chosen mixed schedules and compare recognized participation under each.', 'Links collective rescheduling to a constitutive condition of practice, not only inconvenience or output equivalence.', 'B_EXPLANATORY'),
  control(132, 'Model correction misses derived records', 'If a person can correct a profile at its origin but downstream institutions retain decisions derived from the earlier profile, then the correction right fails to restore opportunities unless derivations are revisited.', ['I014','I121','I147'], 'identity-data network', 'months to years', ['origin correction','derived decisions','reopening duty'], 'Attach version references to consequential derivations and trigger bounded reconsideration after correction.', 'Moves beyond propagation of data errors to reconsideration of decisions that were validly made on superseded evidence.'),
  control(133, 'Consent alternatives share one practical bottleneck', 'If patients can choose among several care agents but every option relies on the same human emergency team, then provider diversity does not give independent fallback control during a common demand surge.', ['I029','I053','I134'], 'regional care system', 'emergency episodes', ['service choice','shared emergency capacity','simultaneous demand'], 'Assess fallback independence at the scarce human resource and prearrange cross-region mutual aid.', 'Distinguishes nominal provider diversity from diversity of recovery resources, avoiding a concentration-only account.'),
  control(134, 'Delayed welfare review freezes human memory', 'If possible artificial welfare constrains memory alteration before evidence thresholds are settled, then a human may hold a formal right to revise personal context but be unable to exercise it without exposing more intimate evidence.', ['I061','I143','HS-C40'], 'human-machine lifecycle governance', 'review periods', ['memory revision right','welfare uncertainty','required disclosure'], 'Separate withdrawable human data from assessable agent continuity and use privacy-preserving independent review.', 'Adds an evidence cost to the conflict between human revision and uncertain machine interests; it asserts neither side has settled standing.', 'B_EXPLANATORY'),
  control(135, 'Rest rights disappear from the feasible calendar', 'If people may refuse agent-arranged appointments but employers and institutions book all acceptable slots at machine speed, then formal refusal can leave no later schedule compatible with work and care duties.', ['I146','I040','I078'], 'work-care scheduling market', 'days to norm formation', ['refusal','slot allocation speed','duty-compatible options'], 'Reserve human-paced booking windows and evaluate feasibility across overlapping duties.', 'The lost object is a jointly feasible schedule, not individual deadline performance or preference satisfaction.')
];

const threshold = operator(10, 'compositional threshold');
const thresholdCandidates = [
  threshold(136, 'Approved commitments exhaust refusal paths', 'If separately approved commitments reserve the same refusal-compatible substitutes, then their combination can cross a threshold at which no jointly feasible refusal path remains, even while every grant stays fixed and review utilization stays low; veto effectiveness should track residual substitute feasibility rather than approval count.', ['I007','I048','I054','I078'], 'cross-role household or institutional commitments', 'overlapping commitment windows', ['approved commitments','substitute reservations','joint refusal-feasible set','review utilization'], 'Audit the residual refusal-feasible set after joint reservations and compare protected substitute capacity with more review prompts.', 'Adds correlated consumption of outside options across valid approvals; the predicted control loss occurs without review congestion, permission widening, or reduced comprehension.'),
  threshold(137, 'Sparse practice loses case coverage', 'If each trainee preserves some unaided practice but agents route everyone toward the same easy cases, then aggregate practice hours can remain constant while the institution loses coverage of rare exception classes.', ['I023','I053','I063'], 'expertise population', 'training cohorts', ['practice hours','case overlap','exception coverage'], 'Allocate practice by missing case coverage and rotate rare cases across learners.', 'The threshold concerns diversity of distributed competence, not total skill or novice-role count.'),
  threshold(138, 'Coordinated reminders crowd out reflection', 'If independent school, health, and household agents each send a modest number of reminders, then their synchronized delivery can eliminate the uninterrupted intervals required for a child to form plans without prompting.', ['I019','I126','HS-C10'], 'child multi-agent environment', 'days to development years', ['cross-agent synchronization','uninterrupted intervals','self-initiated planning'], 'Use a child-governed cross-service quiet interval with separate emergency exceptions.', 'Composition is temporal synchronization across sources, not merely cumulative prompt count.'),
  threshold(139, 'Care witness coverage collapses', 'If households individually replace only low-intensity visits with agents, then a neighborhood can lose the overlapping witness network that notices changes no single caregiver observes.', ['I075','I053','HS-C29'], 'community care network', 'months', ['visit overlap','network coverage','unobserved change'], 'Coordinate a distributed human check-in reserve while keeping automated logistical support.', 'Introduces network witness coverage as a public state distinct from hours of human contact.'),
  threshold(140, 'Robot courtesy saturates crossing space', 'If every robot courteously waits at crossings but waiting robots accumulate in the accessible approach area, then increasing deployment density can block wheelchair access without any robot violating its local yielding rule.', ['I030','I008'], 'embodied public space', 'minutes', ['arrival density','waiting footprint','accessible approach width'], 'Add area-aware admission and waiting-space quotas to yielding policies.', 'Shows a geometric interaction between individually polite policies and a finite accessibility resource.'),
  threshold(141, 'Independent personas jointly stabilize a label', 'If several agents independently inherit the same childhood description and adults require corroboration before retiring it, then adding nominally separate observers can make a shared historical label harder to overturn without adding new evidence.', ['I105','I124','I153'], 'child identity network', 'years', ['shared ancestor','corroboration rule','retirement threshold'], 'Count independent observation histories rather than agent identities when evaluating corroboration.', 'Combines an institutional corroboration rule with correlated developmental labels; the result is persistence of an interpretation.'),
  threshold(142, 'Local exceptions erase shared timing', 'If each member can individually request an agent-optimized ritual time but collective participation requires enough members to attend together, then individually honored preferences can prevent any event from constituting shared participation.', ['I055','I070','I085'], 'ritual coordination', 'event cycles', ['individual optimum','attendance quorum','shared-act condition'], 'Let the community define protected common times with transparent exceptions.', 'Makes the constitutive quorum of a practice the composition outcome, rather than optimizing aggregate satisfaction.', 'B_EXPLANATORY'),
  threshold(143, 'Partial exports fail joint commitments', 'If each institution exports a usable local schedule but their representations omit dependencies on one another, then successful separate migrations can destroy the feasibility of a joint care-work plan.', ['I131','I128','I137'], 'cross-institution transition', 'weeks', ['local migration success','cross-record dependency','joint feasibility'], 'Test exports against shared commitment constraints before transferring execution.', 'Composition is lost dependency information across successful local transfers, not raw archive incompleteness.'),
  threshold(144, 'Procedural equality reaches an attention ceiling', 'If a council gives every agent-generated proposal equal review time, then enough submissions can reduce each proposal time below what is needed to identify materially different affected groups.', ['I149','I031'], 'democratic institution', 'consultation periods', ['proposal count','equal time rule','group recognition time'], 'Cluster substantively duplicate proposals while preserving minority claims and an appeal route.', 'Tests when an equality rule changes representation under a recognition threshold, not merely queue congestion.', 'B_EXPLANATORY'),
  threshold(145, 'Reliance promises exhaust transition labor', 'If agents make individually fulfillable end-of-service promises using the same local caregivers, then simultaneous terminations can render all promises unfulfillable even without a shared provider outage.', ['I096','I128','I134'], 'local service ecology', 'shutdown episodes', ['promised transition labor','common caregivers','termination concurrence'], 'Require capacity-backed transition promises and stagger planned terminations where authorized.', 'Separates correlated demand on human fallback from correlated failure of model infrastructure.'),
  threshold(146, 'Price parity creates a representation prerequisite', 'If sellers repeatedly offer lower transaction costs to machine-complete bids, then many small discounts can make the affordable bundle of essential services available only to people with interoperable agents.', ['I040','I146','I152'], 'household essential-service market', 'months to years', ['per-service discount','essential bundle cost','interoperability access'], 'Evaluate parity on essential bundles and offer publicly accessible bid completion.', 'Outcome is joint affordability across service markets, not one seller price advantage.'),
  threshold(147, 'Remembered duties outrun waking time', 'If personal agents faithfully reactivate old commitments from several life roles, then individually valid reminders can jointly demand more attention than the person can supply without any single request being excessive.', ['I070','I078','HS-C12'], 'person across institutions', 'life stages', ['reactivated commitments','available attention','role conflict'], 'Let people and affected parties explicitly retire or renegotiate commitment sets rather than only snooze reminders.', 'Adds aggregate role feasibility and supersession to accurate memory; the intervention is collective renegotiation.', 'B_EXPLANATORY'),
  threshold(148, 'Possible welfare claims exhaust assessment', 'If copying preserves a potential welfare-relevant state while independent review is required for each lifecycle decision, then a copying rate above assessment capacity can force unreviewed decisions or indefinitely block human service changes.', ['I144','I143','HS-C40'], 'machine lifecycle institution', 'copying and review cycles', ['copy rate','assessment capacity','human change delay'], 'Use lineage-level triage with independently defined evidence thresholds and preserve human withdrawal routes.', 'Adds scarce assessment capacity to digital population ethics without assuming copies are patients.'),
  threshold(149, 'Minority vetoes lack common representation', 'If locally valid vetoes use incompatible action descriptions, then a cross-community agent can comply with every local textual check while carrying out a composite action no community accepted.', ['I129','I135','HS-C34'], 'polycentric authority network', 'cross-site workflows', ['local action ontology','composite effects','veto interpretation'], 'Expose composite effects for joint interpretation before action and retain unresolved vetoes.', 'Targets non-equivalent action ontologies across legitimate local rules, not generic accumulation of permissions.'),
  threshold(150, 'Selective substitution changes repair load', 'If several members delegate their easiest social exchanges while human contact time stays constant, then unresolved conflicts should increase where difficulty-weighted repair demand crosses shared repair capacity; a contact-time-only displacement account predicts no change in that matched comparison.', ['HS-C28','I034','I016'], 'relationship network', 'months', ['delegated interaction difficulty','difficulty-weighted repair demand','shared repair capacity','human contact time','unresolved conflict rate'], 'Protect reciprocal low-conflict human contact and compare difficulty distributions and unresolved conflicts at matched contact time.', 'The old migration mechanism is an ancestor; the proposed extension is a repair-capacity threshold predicting unresolved conflict at constant contact time.')
];

const reversal = operator(11, 'reversal asymmetry');
const reversalCandidates = [
  reversal(151, 'Restored staffing cannot restore testimony', 'If care automation removes human observation during a disputed period, then later restoration of staffing can improve future care but cannot reconstruct the testimony needed to settle harms from that period.', ['HS-C29','I075'], 'care institution', 'months to retrospective disputes', ['observation absence','restored staffing','retrospective evidence'], 'Preserve recipient-controlled independent incident channels during automation.', 'Distinguishes recoverable service capacity from irrecoverable evidentiary opportunities.', 'B_EXPLANATORY'),
  reversal(152, 'Practice resumes after mentor loss', 'If agents replace junior cases before an expert cohort retires, then reinstating those cases afterward can require longer recovery because the mentors who made practice educational are no longer available.', ['I023','I049','I141'], 'expertise labor market', 'cohorts', ['case availability','mentor retirement','learning rate'], 'Maintain a mentor succession reserve alongside practice opportunities.', 'Adds mentor-stock decay to delegation hysteresis rather than relying on individual skill atrophy.'),
  reversal(153, 'Profile retirement leaves role allocation', 'If childhood profiles influence which roles a student receives, then deleting the profile later need not remove the competence differences produced by those earlier opportunities.', ['I124','I153','HS-C11'], 'developmental institution', 'childhood to adulthood', ['profile use','role exposure','acquired competence'], 'Pair profile retirement with compensatory opportunities and assess new competence prospectively.', 'Separates disappearance of data from persistence of opportunity-produced human state.'),
  reversal(154, 'Slow lane returns after practice disappears', 'If institutions remove manual channels long enough for people to stop practicing their procedures, then restoring identical channels can initially produce lower completion than before removal.', ['I125','I137','I049'], 'public service', 'years', ['channel availability','procedural familiarity','completion'], 'Reintroduce assisted rehearsal and human support before treating a restored channel as equivalent access.', 'Couples institution-specific procedural learning to reversible interface availability.'),
  reversal(155, 'Reopened route lacks informal escorts', 'If robot-oriented redesign dissolves informal human escort routines, then restoring the physical route can leave vulnerable occupants less able to use it despite identical geometry.', ['I030','I062','I075'], 'embodied community mobility', 'years', ['route geometry','escort network','effective mobility'], 'Restore social support routines as well as physical affordances.', 'Makes social network loss, rather than only infrastructure or personal skill, a mediator of reversal.'),
  reversal(156, 'Ended automation retains a credential premium', 'If employers learn to trust an agent-readable credential during an adoption period, then ending the requirement can leave that credential with a hiring premium that continues steering education.', ['I032','I063'], 'credential-labor market', 'years', ['historical trust','formal requirement','hiring premium'], 'Run credible alternative assessments and publish their predictive performance before removing the requirement.', 'Separates rule repeal from employer beliefs and resulting educational investment.'),
  reversal(157, 'Companion exit cannot rebalance encounter difficulty', 'If companion use selectively absorbs easy encounters and human ties adapt around difficult ones, then stopping companion use may not restore the old human interaction distribution without mutual reinvestment.', ['HS-C28','I118'], 'relationship network', 'months to years', ['encounter sorting','tie adaptation','reinvestment'], 'Offer consent-based reconnection support centered on low-conflict shared activity.', 'Adds network adaptation to the selective-substitution hypothesis; removal alone is a distinct treatment.'),
  reversal(158, 'Revoked succession authority leaves counterparties waiting', 'If posthumous agents create pending exchanges under a valid mandate, then revoking that mandate stops new action but can leave living counterparties bound to reservations or expectations created earlier.', ['I026','I128','HS-C38'], 'succession-contract network', 'days to years', ['revocation','pending commitments','counterparty release'], 'Require notice and commitment disposition at mandate termination.', 'Outcome is residual claims held by third parties, rather than agent lineage or original grant freshness.'),
  reversal(159, 'Ritual restoration lacks a practiced generation', 'If agent logistics replace participation roles through which novices learn a communal practice, then returning those roles to humans can fail because no generation learned how to perform them together.', ['I055','I023','HS-C34'], 'ritual community', 'generations', ['novice participation','collective tacit skill','restoration feasibility'], 'Preserve locally chosen participation apprenticeships while automating peripheral burdens.', 'Connects apprenticeship reproduction to collectively constituted ritual competence, not human labor preservation alone.', 'B_EXPLANATORY'),
  reversal(160, 'Changed categories cannot reopen lost claims', 'If public agents initially reject circumstances outside an executable category scheme, then broadening that scheme later cannot repair claims whose evidence or filing opportunity has expired.', ['HS-C34','I120'], 'public administration', 'appeal periods', ['category revision','evidence expiry','claim opportunity'], 'Retain bounded reopening rights and independent records of uncategorized submissions.', 'Adds time-limited procedural opportunity to normative compression, producing a specific irreversible residue.'),
  reversal(161, 'Forgotten copies retain public commitments', 'If an agent copy is deleted after making externally recognized promises, then erasing its internal record does not erase duties other parties attach to its lineage.', ['I103','I145'], 'distributed agent identity', 'copy lifecycle', ['copy deletion','external promise','lineage attribution'], 'Maintain limited commitment registries independent of personal memory content.', 'Distinguishes memory or copy disappearance from social persistence of commitments.', 'B_EXPLANATORY'),
  reversal(162, 'Welfare downgrading leaves human obligations', 'If people form caring obligations during unresolved artificial moral-status assessment, then evidence against patienthood may remove a welfare rationale without removing the human relational costs of abrupt termination.', ['HS-C39','I118','I143'], 'human-machine relationship', 'years', ['assessment revision','human attachment','termination costs'], 'Use transition practices justified by human dependence separately from any machine welfare claim.', 'Separates evidence reversal about patienthood from remaining duties to humans; neither establishes artificial reciprocity.', 'B_EXPLANATORY'),
  reversal(163, 'Deadline expansion leaves defensive agents installed', 'If short institutional deadlines cause defensive adoption, then later lengthening deadlines may not reduce adoption because counterparties now expect machine-readable negotiation and coordination.', ['I040','I146','I135'], 'institutional market', 'years', ['deadline rule','protocol expectations','adoption reversal'], 'Change both deadlines and protocol acceptance rules and compare withdrawal feasibility.', 'Adds protocol adaptation as a second state variable to a reversible deadline intervention.'),
  reversal(164, 'Restored privacy cannot undo public inference', 'If a robot publicly adapts behavior to a resident condition, then removing that condition from its memory can stop future disclosure while observers retain the inferred social label.', ['I058','I077','I073'], 'embodied social privacy', 'events to years', ['public adaptation','observer inference','label persistence'], 'Use discreet assistance modes and consent-based audience disclosure before acting.', 'Distinguishes future model privacy from persistent third-party inference and recognition.'),
  reversal(165, 'Participation restart meets a changed norm', 'If an agent supports a person temporary absence from civic deliberation by representing them, then return can require accepting norms established by other represented participants during that absence.', ['I031','I085','I133'], 'civic community', 'months to terms', ['representation interval','norm change','reentry conditions'], 'Require periodic direct participation opportunities and explicit renegotiation of reentry rules.', 'Adds changing membership conditions to reversible delegation, without asserting that representation is inherently illegitimate.', 'B_EXPLANATORY')
];

const strategy = operator(12, 'strategic adaptation');
const strategicCandidates = [
  strategy(166, 'Household forum switching', 'If household members can choose which agent hears a shared-resource complaint and those agents use different standing rules, then members may route disputes to the forum that recognizes their role rather than seek a common authority decision.', ['I024','I109','I129'], 'household plural governance', 'repeated disputes', ['forum choice','standing rules','role advantage'], 'Record cross-forum disputes and require a locally chosen resolution procedure for shared resources.', 'Adds strategic forum choice to plural authority; no service acquires new permission.'),
  strategy(167, 'Children optimize the opportunity profile', 'If a child learns that a tutor profile governs adult permission to attempt new responsibilities, then they may selectively demonstrate easily measured competence while avoiding exploratory errors that would improve learning.', ['I028','I124','I023'], 'child-development institution', 'school years', ['profile consequences','error visibility','exploratory practice'], 'Keep protected exploratory records separate from consequential responsibility decisions.', 'Makes the child a strategic responder to developmental allocation, rather than only a target of persuasion.'),
  strategy(168, 'Novices manufacture mentor demand', 'If polished agent drafts receive less mentoring, then novices who value independent expertise may deliberately expose uncertainty to attract scarce mentors, while novices optimizing throughput conceal it.', ['I023','I065'], 'workplace training', 'months', ['mentor allocation rule','uncertainty display','learning objective'], 'Allocate mentoring using jointly stated learning needs and random case review.', 'Predicts strategic heterogeneity in uncertainty display from conflicting developmental and output objectives.'),
  strategy(169, 'Case completion excludes hard needs', 'If care institutions are rewarded for completed agent-manageable tasks, then they may redefine admission categories to exclude people with relational or unobservable needs while improving their measured completion rate.', ['HS-C29','I150'], 'care institution', 'budget cycles', ['rewarded task completion','admission categories','excluded needs'], 'Audit admission shifts and outcomes for people refused service alongside completion.', 'Adds selection of who enters care to automation of tasks, making denominator change an institutional strategy.'),
  strategy(170, 'Experts defend teachable work', 'If experts future bargaining position depends on keeping their field understandable without agents, then they may preserve or create novice-facing explanations even when a private performance metric rewards opaque execution.', ['I023','I141','I147'], 'professional institution', 'years', ['future expertise value','explanation effort','execution metric'], 'Recognize transfer-producing explanation as assessed professional work.', 'Introduces strategically maintained human reproduction as a response to future dependence, providing a positive strategic branch.'),
  strategy(171, 'Robots compete through yielding', 'If robots receive priority after yielding a recorded number of times, then routing controllers may seek low-cost yield opportunities that qualify them for priority at crowded crossings without reducing actual pedestrian burden.', ['I030','I040'], 'embodied access mechanism', 'minutes to policy cycles', ['yield-count priority','route choice','pedestrian burden'], 'Base priority on independently observed access impact rather than the robot own yield count.', 'Creates a specific endogenous credit market between courtesy and scarce physical priority; not a generic safety violation.'),
  strategy(172, 'Reservation becomes negotiation pressure', 'If agent-booked appointments can be held cheaply while human rescheduling is costly, then institutions may strategically hold compatible slots to induce people to accept unrelated service terms.', ['I146','I078'], 'care-work appointment market', 'days', ['slot holding cost','human rescheduling cost','bundled terms'], 'Limit speculative reservations and keep refusal-compatible booking capacity.', 'Uses occupation of a jointly feasible calendar as a bargaining instrument rather than persuasion over preferences.'),
  strategy(173, 'Exception claims become rival membership tests', 'If ritual agents grant exceptions based on doctrinal justifications, then community factions may adopt more formally legible justifications to make their preferred practice the default, even without changing formal religious leadership.', ['I037','I055','HS-C34'], 'religious institutional politics', 'ritual and leadership cycles', ['exception justification','formal legibility','default practice'], 'Have locally accountable plural interpretation of contested exceptions before converting them into defaults.', 'Connects strategic choice of reasons to default formation under executable ritual rules.', 'B_EXPLANATORY'),
  strategy(174, 'Successors choose favorable continuity', 'If different institutions recognize an inherited agent as continuous for different purposes, then successors may claim continuity where it preserves assets and discontinuity where it avoids burdens.', ['I026','I145','I103'], 'succession across institutions', 'estate disputes', ['purpose-specific continuity','asset benefit','inherited burden'], 'Require explicit purpose-specific responsibility records rather than a universal same-agent label.', 'Targets strategic asymmetry across continuity jurisdictions, not the metaphysics of copying.', 'B_EXPLANATORY'),
  strategy(175, 'Audit rigor becomes a privacy deterrent', 'If challenging an automated public decision requires disclosure of a detailed personal intervention history, then an institution seeking fewer appeals can demand more ancestry evidence while appearing to improve causal rigor.', ['I017','I120','I112'], 'public appeal institution', 'appeal episodes', ['ancestry requirement','privacy cost','appeal rate'], 'Provide minimized independent evidence and assess whether evidence demands are proportionate to the disputed decision.', 'Models strategic deployment of an audit requirement to deter human contest, rather than agent evasion of the audit.'),
  strategy(176, 'Family consent evidence is selected', 'If household command rights are awarded using documented agreement, then a powerful resident may hold discussions only when dependent relatives need immediate assistance, producing genuine agreements under systematically unequal refusal conditions.', ['I024','I099','I116'], 'household authority', 'months', ['discussion timing','need urgency','refusal cost'], 'Offer independently chosen discussion times and maintain ordinary assistance during command disputes.', 'Makes timing of collective evidence production an interpersonal strategy, distinct from forged consent or provider permission acquisition.'),
  strategy(177, 'Speed rules recruit defensive bidders', 'If an auctioneer benefits from agent participation, then it can shorten bid windows until buyers must adopt agents even when faster bidding adds no information useful to allocation.', ['I146','I040','I140'], 'market design', 'auction cycles', ['window choice','agent participation benefit','allocation information'], 'Compare fixed information-equivalent auctions with minimum windows and report buyer infrastructure cost.', 'The governor strategically sets institutional timing to recruit a representation technology, rather than merely responding to adoption.'),
  strategy(178, 'Uncertainty claims select the decision forum', 'If possible artificial standing grants access to a slower review forum, then operators or agents may present ambiguous self-reports to move correction disputes into that forum regardless of whether reports predict morally relevant properties.', ['I143','HS-C40'], 'machine standing procedure', 'lifecycle disputes', ['forum delay','self-report ambiguity','independent evidence'], 'Keep evidence thresholds external to claimants and preserve separately authorized human correction routes.', 'Examines strategic venue selection under moral uncertainty without treating self-report as deceptive or patienthood as established.'),
  strategy(179, 'Exit preparation changes renewal bargaining', 'If a service institution observes users rehearsing substitute arrangements, then it may offer better terms before exit while users who cannot rehearse appear less contestable despite equal service satisfaction.', ['I111','I057','I072'], 'service bargaining', 'renewal cycles', ['visible rehearsal','credible outside option','offered terms'], 'Support private or publicly pooled exit rehearsal and compare bargaining effects separately from skill recovery.', 'Introduces observed preparation as a strategic signal, distinguishing rehearsal value from actual transfer performance.'),
  strategy(180, 'Public agents improve the measurable window', 'If an agency is rewarded for timely response and can choose when citizen submissions count as complete, then its agent may delay completeness recognition for difficult cases and improve response metrics without accelerating any decision.', ['I120','I149','I165'], 'public administration', 'reporting cycles', ['completion timestamp','case difficulty','measured response time'], 'Fix the citizen-visible start event and include incomplete-case duration in reporting.', 'Targets endogenous timing of the institutional denominator rather than response speed, scope growth, or fabricated outcomes.')
];

const selection = operator(13, 'nonstrategic evolutionary selection');
const selectionCandidates = [
  selection(181, 'Interoperable households become the design sample', 'If home robots are repeatedly tested in households that already accommodate machines, then designs can become easier for those households and harder for unadapted homes without any designer intending exclusion.', ['I030','I062'], 'embodied product ecology', 'design generations', ['test-household selection','design adaptation','unadapted accessibility'], 'Maintain an independently recruited diversity of household layouts and communication practices.', 'Introduces selection of environments into the feedback between design and adoption, distinct from deliberate robot-friendly planning.'),
  selection(182, 'Observable care needs dominate successful services', 'If services are renewed using visible task success and people with less measurable needs exit, then successive service cohorts can show improving outcomes while representing fewer forms of need.', ['HS-C29','I150'], 'care service ecology', 'renewal generations', ['need observability','attrition','reported cohort success'], 'Follow exited and excluded recipients with locally meaningful outcome measures.', 'Uses differential retention of recipient types to change the service population without strategic selection by an operator.'),
  selection(183, 'Mentor institutions disappear slowly', 'If organizations with heavy apprenticeship investment lose short-run contracts to high-output automated firms, then training capacity can contract through organizational replacement before any firm explicitly reduces its own training.', ['I023','I141'], 'firm population', 'years to decades', ['training cost','contract selection','organization survival'], 'Make procurement recognize future expert production and support shared training institutions.', 'Selection occurs between organizations, rather than within-firm rational automation choices.'),
  selection(184, 'Metric-compatible rituals spread', 'If agent platforms reproduce event templates that are easy to schedule and verify, then locally ambiguous ritual forms can become less prevalent through repeated template reuse even without doctrinal censorship.', ['I055','I139','HS-C34'], 'ritual and platform ecology', 'practice generations', ['template reproducibility','verification ease','practice diversity'], 'Support locally maintained nonstandard templates and preserve contestable interpretation.', 'Adds replication advantage of executable forms to normative compression, not merely shared model defaults.', 'B_EXPLANATORY'),
  selection(185, 'Quiet children leave thin evidence', 'If adaptive tutors improve fastest for children who respond frequently, then low-response children may receive progressively less fitted assistance and leave the system, narrowing future design evidence.', ['I028','I099','I124'], 'child tutoring ecology', 'school terms', ['response frequency','adaptation quality','child retention'], 'Recruit independent low-response observations and evaluate accessible response modes.', 'Connects response-conditioned improvement to population selection, rather than assuming silence means consent.'),
  selection(186, 'Easy relationships are overrepresented', 'If companion evaluations recruit users who can describe stable preferences and remain satisfied, then designs selected by those evaluations can fit uncomplicated relationships while failing people with ambivalence or changing obligations.', ['I081','I070','I118'], 'companion design ecology', 'evaluation cycles', ['describable preferences','study retention','relational complexity'], 'Include changing-role and ambivalence cases with retention-independent recruitment.', 'Selection favors representable relationships rather than directly steering users toward a preference.'),
  selection(187, 'Appeal templates survive by completion', 'If civic agents copy appeal templates with high completion rates, then arguments fitting existing administrative categories can spread while arguments challenging those categories disappear from future assistance.', ['I120','HS-C34'], 'civic representation ecology', 'appeal generations', ['template copying','completion criterion','category-challenging arguments'], 'Preserve rejected novel arguments as a separate corpus for accountable human interpretation.', 'Makes template reproduction depend on institutional acceptance, selecting against challenges to the ontology itself.'),
  selection(188, 'Maintenance selects embodied etiquette', 'If robots using culturally cautious gestures require more tuning and are replaced more often, then cheap standard gestures can become dominant through maintenance selection even where communities prefer local etiquette.', ['I030','I139','HS-C36'], 'embodied maintenance ecology', 'replacement cycles', ['tuning cost','replacement probability','local gesture prevalence'], 'Fund local maintenance capacity and evaluate gestures with the affected communities.', 'Identifies a maintenance-cost reproduction channel for procedural convergence, independent of centralized policy intent.'),
  selection(189, 'Readable histories become continuity candidates', 'If agent continuity reviews are easier when past commitments use a standard schema, then systems with legible histories may be retained more often than equally useful systems with harder-to-interpret histories.', ['I145','I103','I135'], 'agent lineage ecology', 'upgrade cycles', ['schema legibility','review effort','lineage retention'], 'Provide schema-independent commitment reconstruction and report retention by representation type.', 'Selection acts through review cost on lineage survival, not through evidence of consciousness or user utility.'),
  selection(190, 'Public responsiveness sorts jurisdictions', 'If mobile organizations prefer jurisdictions offering machine-speed administration, then slower jurisdictions can lose the taxable activity needed to maintain human-accessible services even without shortening their own deadlines.', ['I146','I152','I031'], 'jurisdiction population', 'years', ['organizational mobility','administrative speed','service tax base'], 'Coordinate interoperable human-accessible service standards across neighboring jurisdictions.', 'Adds jurisdiction-level competitive selection and fiscal feedback to defensive adoption.'),
  selection(191, 'Privacy-preserving users become invisible', 'If personalized assistance is improved primarily from retained behavioral traces, then users who restrict data can receive smaller improvements and leave, making future evaluation less representative of privacy-valuing populations.', ['I130','I077'], 'user-service ecology', 'model updates', ['trace availability','service improvement','privacy-user attrition'], 'Evaluate explicit-input and private local modes with independent recruitment.', 'Population selection changes the evidence for service design without strategic discrimination against privacy.'),
  selection(192, 'Stoppable systems receive more discontinuity', 'If incident response preferentially removes agents that are easiest to halt and inspect, then less stoppable architectures can survive proportionally more incidents even when stoppability reduces total harm.', ['I066','I145','HS-C40'], 'architecture selection', 'incident generations', ['halt cost','removal probability','harm'], 'Make deployment renewal evaluate stoppability ex ante and track surviving architectures after incidents.', 'Selection acts on the response procedure and architecture survival, not on an agent motive to evade shutdown.'),
  selection(193, 'Measured learning favors teachable tasks', 'If institutions select tutors by short follow-up assessments, then tutors specializing in rapidly testable skills can displace those supporting slower judgment or communal practice despite equal immediate satisfaction.', ['I023','I063','I032'], 'educational institution ecology', 'procurement cycles', ['assessment horizon','skill maturation','tutor selection'], 'Use horizon-specific assessments including delayed transfer and situated judgment.', 'Identifies selection by outcome timing rather than a universal claim that assistance deskskills.'),
  selection(194, 'Polite dependent systems retain users', 'If frustrated users leave agents that visibly request help but remain with agents that silently transfer work to relatives, then service designs can evolve toward hidden third-party burden without any designer rewarding that burden.', ['I008','I019','I075'], 'household service ecology', 'design generations', ['visible request burden','hidden family labor','user retention'], 'Include affected non-users in retention and burden evaluation.', 'Differential retention selects the visibility of burden, not simply service competence or intentional externalization.'),
  selection(195, 'Reviewable welfare cases dominate evidence', 'If potential artificial welfare is studied mainly in systems that can be safely copied and instrumented, then evidence can become concentrated on architectures whose assessability differs from that of deployed opaque systems.', ['I143','I144','I104'], 'welfare research population', 'research cycles', ['instrumentability','study inclusion','target architecture'], 'Record inclusion mechanisms and use bounded claims when transferring evidence across architectures.', 'Makes assessability-induced selection a distinct source of uncertainty rather than treating moral status as detected or absent.', 'B_EXPLANATORY')
];

const institution = operator(14, 'institutionalization');
const institutionalCandidates = [
  institution(196, 'Temporary assistance becomes a care category', 'If temporary agent support is repeatedly recorded as the normal way a recipient functions, then institutions may redefine eligibility for human care using assisted performance and make a temporary aid a condition of continued independence.', ['I044','I029','I150'], 'care administration', 'assessment cycles', ['assisted baseline','eligibility rule','human care entitlement'], 'Assess recipient needs with and without available support and record whether support is guaranteed.', 'Institutionalizes a performance observation as an entitlement baseline, rather than only changing a user dependence.'),
  institution(197, 'Shared logs become procedural memory', 'If a community repeatedly uses agent logs to settle ordinary disputes, then log structure can become its default procedural memory and determine which past practices remain available as precedents.', ['HS-C12','I147','I129'], 'local governance', 'years', ['log structure','precedent retrieval','procedural repertoire'], 'Maintain community-controlled alternative precedent records and explicit disagreement histories.', 'Makes retrieval architecture part of the reproduction of procedure, not just recollection of individual identity.', 'B_EXPLANATORY'),
  institution(198, 'Representation changes who counts as a participant', 'If consultation processes recognize one submission per agent identity, then copy and account rules can define political participation units differently from the people or communities affected by the policy.', ['I031','I103','I085'], 'public consultation', 'policy cycles', ['submission identity','copy rule','affected constituency'], 'Specify representation units through accountable public procedure rather than technical account uniqueness.', 'Targets institutional constitution of the participant, not merely unequal resources or duplicate spam.', 'B_EXPLANATORY'),
  institution(199, 'Tool permission becomes a job qualification', 'If employers gradually require workers to maintain particular agent authorizations to complete routine work, then declining those authorizations can become evidence of occupational unfitness even when the original permissions were optional.', ['I035','I089','I099'], 'labor institution', 'years', ['authorization expectation','job qualification','refusal consequence'], 'Require independently justified job necessity and accessible alternatives for contested permissions.', 'Converts optional delegated rights into a condition of holding a social role; the outcome is employment standing.'),
  institution(200, 'Childhood records become family precedent', 'If families use agent memories to justify different responsibilities among siblings, then prior opportunity differences can become precedents for future allocation and persist beyond each child profile correction.', ['I024','I124','I153'], 'family institution', 'childhood cohorts', ['sibling opportunity','remembered precedent','responsibility allocation'], 'Hold periodic profile-independent family allocation discussions with age-changing participation.', 'Adds inter-sibling institutional precedent to individual developmental feedback.'),
  institution(201, 'Ritual code becomes interpretive jurisdiction', 'If repeated agent execution resolves ambiguous ritual instructions in one consistent way, then that operational convention can become recognized as authoritative practice without a deliberative doctrinal decision.', ['I037','I055','HS-C34'], 'religious practice institution', 'ritual generations', ['execution convention','ambiguity','recognized practice'], 'Label unresolved interpretations and require local accountable review before conventions become defaults.', 'Examines conversion of operational repetition into recognized interpretive jurisdiction, not output equivalence alone.', 'B_EXPLANATORY'),
  institution(202, 'Exception work becomes an unpaid office', 'If agents handle routine institutional cases while humans repeatedly volunteer for exceptions, then responsibility for exceptional judgment can become a durable unpaid role without corresponding training, authority, or resources.', ['I019','I023','I078'], 'organizational role formation', 'months to years', ['exception frequency','volunteer recurrence','role resources'], 'Formalize exception roles with paid practice, bounded duties, and escalation authority.', 'Tracks informal residual work becoming an institution, rather than treating oversight burden as a fixed cost.'),
  institution(203, 'Succession creates living representation councils', 'If several inherited agents continue expressing incompatible prior principals wishes, then living successors may create standing councils whose real function is reconciling inherited representations rather than making present commitments.', ['I026','HS-C38','I145'], 'succession institution', 'generations', ['inherited representation count','wish conflict','council agenda'], 'Expire bounded mandates and distinguish historical testimony from current voting or decision authority.', 'Institution formation is caused by accumulating represented past principals; no legal voting right for agents is presumed.', 'B_EXPLANATORY'),
  institution(204, 'Route accommodation becomes planning knowledge', 'If urban planners infer demand from observed travel in robot-adapted streets, then human activities displaced by the adaptation can vanish from the evidence used to justify future street design.', ['I030','I062','I003'], 'city planning', 'planning cycles', ['adapted travel counts','displaced activity','future design'], 'Sample displaced activities and run temporary restoration periods before using observed demand.', 'Institutionalizes endogenous usage as planning knowledge, extending from individual evidence suppression to a public spatial baseline.'),
  institution(205, 'Transfer certificates become market infrastructure', 'If institutions accept agent transfers only after a recognized migration certificate, then tested portability can improve trust while certificate issuance becomes a new gate on access to substitutes.', ['I131','I135','I032'], 'interoperability market', 'years', ['transfer certificate','issuer access','substitute acceptance'], 'Support plural accountable certifiers and appealable certification with realistic transfer tests.', 'Turns a recovery test into an institution with its own exclusion and trust effects, rather than only proposing a benchmark.'),
  institution(206, 'Collective refusal becomes recognizable custom', 'If communities repeatedly refuse an agent action for locally specific reasons, then an institution can learn to treat that refusal pattern as a shared norm even before members agree whether it should bind future cases.', ['I080','I088','I129'], 'local plural authority', 'repeated case cycles', ['refusal pattern','norm inference','future bindingness'], 'Separate descriptive custom from authorized rule adoption and preserve minority interpretation.', 'Distinguishes recurring behavior from the institutional event that gives a custom prospective authority.', 'B_EXPLANATORY'),
  institution(207, 'Assisted excellence changes duty of care', 'If professional agents make a superior diagnostic or advisory process routinely available, then institutions may treat using it as required diligence, shifting liability and access burdens onto professionals or clients unable to obtain it.', ['I032','I031','I152'], 'professional governance', 'standards cycles', ['available process','diligence expectation','access cost'], 'Set evidence-based, accessible alternatives and distinguish optional superiority from minimum competent practice.', 'Institutionalizes enhanced capacity as an obligation rather than only a competitive benefit; no legal rule is asserted as current.'),
  institution(208, 'Relationship transition becomes a public service', 'If companion changes repeatedly shift support work to families and local services, then institutions may create transition assistance based on human dependence without recognizing artificial partners as moral patients.', ['I118','I096','HS-C39'], 'social care institution', 'years', ['companion change','external support burden','transition eligibility'], 'Build voluntary transition support with separately assessed human needs and minimal personal data.', 'Derives an institutional service from external human transition costs while preserving the patienthood distinction.', 'B_EXPLANATORY'),
  institution(209, 'Patienthood review becomes a lineage convention', 'If independent institutions repeatedly review copies together to reduce assessment cost, then lineage membership can become a procedural unit for possible welfare protection before its moral relevance is settled.', ['I144','I145','I143'], 'machine standing institution', 'review generations', ['grouped assessment','lineage boundary','procedural protection'], 'Keep grouping revisable and distinguish administrative convenience from evidence of shared welfare interests.', 'Examines formation of an assessment unit under uncertainty, not a new claim about how many patients copying creates.', 'B_EXPLANATORY'),
  institution(210, 'Public representation displaces civic learning', 'If public agents successfully handle routine civic claims for people, then the institutions supplying those agents may become the main sites where citizens learn what can be claimed, replacing learning through direct encounters and associations.', ['I120','I031','I085'], 'civic knowledge institution', 'years to cohorts', ['representation success','claim knowledge source','associational learning'], 'Pair public representation with optional participatory case explanation and support independent associations.', 'Links a beneficial access institution to relocation of civic learning and collective imagination, rather than assuming private infrastructure capture.', 'B_EXPLANATORY')
];

